using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

namespace AsyncAwaitDeepDemo
{
    public class Program
    {
        public static async Task Main()
        {
            await DemonstrateStateMachine();
            await DemonstrateWhenAllVsSequential();
            DemonstrateValueTaskCaching();
            await DemonstrateCancellation();
        }

        // 状态机：多个 await 的暂停-恢复
        static async Task DemonstrateStateMachine()
        {
            Console.WriteLine("[StateMachine] 开始，线程=" + Thread.CurrentThread.ManagedThreadId);

            int step1 = await ComputeAsync(1);
            Console.WriteLine($"[StateMachine] step1={step1}，线程=" + Thread.CurrentThread.ManagedThreadId);

            int step2 = await ComputeAsync(2);
            Console.WriteLine($"[StateMachine] step2={step2}，线程=" + Thread.CurrentThread.ManagedThreadId);

            // 两次 await 之间可能切换线程（线程池环境）
        }

        static async Task<int> ComputeAsync(int value)
        {
            await Task.Delay(50); // 模拟 IO
            return value * 10;
        }

        // WhenAll vs 逐个 await 的耗时差异
        static async Task DemonstrateWhenAllVsSequential()
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            await SimulateIOAsync("A", 200);
            await SimulateIOAsync("B", 200);
            await SimulateIOAsync("C", 200);
            sw.Stop();
            Console.WriteLine($"[Sequential] 串行总耗时={sw.ElapsedMilliseconds}ms");

            sw.Restart();
            await Task.WhenAll(
                SimulateIOAsync("A", 200),
                SimulateIOAsync("B", 200),
                SimulateIOAsync("C", 200));
            sw.Stop();
            Console.WriteLine($"[WhenAll] 并行总耗时={sw.ElapsedMilliseconds}ms");
        }

        static async Task SimulateIOAsync(string name, int ms)
        {
            await Task.Delay(ms);
            Console.WriteLine($"  {name} 完成");
        }

        // ValueTask：缓存命中时零分配
        static void DemonstrateValueTaskCaching()
        {
            var cache = new ConcurrentDictionary<int, int>();
            cache[42] = 999;

            // 第一次调用：缓存命中，同步返回，零分配
            ValueTask<int> vt = GetValueOrFetchAsync(cache, 42);
            Console.WriteLine($"[ValueTask] 缓存命中，IsCompleted={vt.IsCompleted}");

            // 注意：ValueTask 只能 await 一次
        }

        static async ValueTask<int> GetValueOrFetchAsync(ConcurrentDictionary<int, int> cache, int key)
        {
            if (cache.TryGetValue(key, out var cached))
                return new ValueTask<int>(cached); // 零分配

            // 缓存未命中，走异步 IO
            await Task.Delay(100);
            int value = key * 23;
            cache[key] = value;
            return value;
        }

        // CancellationToken 超时与取消
        static async Task DemonstrateCancellation()
        {
            using var cts = new CancellationTokenSource();
            cts.CancelAfter(300); // 300ms 后自动取消

            try
            {
                await LongRunningAsync(cts.Token);
                Console.WriteLine("[Cancel] 不应该到这里");
            }
            catch (OperationCanceledException)
            {
                Console.WriteLine("[Cancel] 任务被取消（超时）");
            }
        }

        static async Task LongRunningAsync(CancellationToken ct)
        {
            for (int i = 0; i < 100; i++)
            {
                ct.ThrowIfCancellationRequested();
                await Task.Delay(50, ct);
                Console.WriteLine($"[LongRunning] 进度={i + 1}");
            }
        }
    }
}
